import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`service-packaging`,heroTitle:`Package your services in minutes`,heroSubtitle:`Perplexity Computer analyzes your freelance brand, structures your offerings into tiered packages, and builds a pricing page — automatically.`,inputUrlCta:`Package my services`,inputUrlPlaceholder:`yourportfolio.com`,inputUrlPrefill:`Go to {url} and do a deep analysis of this freelancer or agency's services, skills, positioning, target audience, and pricing signals. Then build a complete service packaging strategy with the following deliverables: 1) Extract all services offered, unique selling points, testimonials, case studies, and any existing pricing. 2) Research competitor freelancers in the same niche to benchmark pricing and packaging structures. 3) Create 3 tiered service packages (Starter, Professional, Premium) with clear names, descriptions, deliverables, timelines, and recommended pricing for each. 4) Write persuasive package descriptions that speak to different buyer segments — budget-conscious clients, mid-market, and premium buyers. 5) Suggest 2-3 add-on services or upsells that complement the core packages. 6) Build a polished, client-ready pricing page as a deployed web app that showcases all three tiers with feature comparisons, CTAs, and FAQ sections addressing common objections. 7) Include a one-page sales script for presenting each package on discovery calls.`,heroOverlaySteps:[`Analyzing your services, skills, and positioning`,`Researching competitor pricing and packaging in your niche`,`Structuring tiered packages with pricing and deliverables`,`Polished packages and pricing page — ready to send to clients`],generatingSteps:[`Visiting {url} to extract your services, positioning, and client signals`,`Designing an agent to benchmark competitor pricing and package structures`,`Configuring tiered service packages with descriptions, deliverables, and pricing`,`Setting up your client-ready pricing page and sales scripts`],featureSectionTitle:`From portfolio to packaged offerings`,featureCardTitles:[`Connects to your freelance stack`,`Outputs you can sell today`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Notion, Google Docs, Google Sheets, Canva, Stripe — Computer builds your packages and pipes deliverables into the tools you already use to run your business.`,`Three tiered service packages. A deployed pricing page. Competitor benchmarks. Add-on upsells. Discovery call scripts for every tier.`],capabilitySectionTitle:`Your strategist, on autopilot`,capabilitySectionSubtitle:`Paste your URL, step away, come back to packaged services ready to sell.`,capabilityCards:[{title:`Service Audit`,description:`Computer can analyze your portfolio, testimonials, and case studies — and map every skill into clear, sellable service offerings.`},{title:`Competitor Benchmarking`,description:`Computer can research freelancers in your niche — and benchmark their pricing, packaging, and positioning against yours.`},{title:`Tiered Packaging`,description:`Computer can structure your services into three buyer-aligned tiers — with deliverables, timelines, and pricing that maximize revenue per client.`},{title:`Connect Your Tools`,description:`Computer can sync with Notion, Google Docs, Google Sheets, Stripe, and Canva — build workflows across your entire freelance stack.`},{title:`Learn & Refine`,description:`Computer can remember your past packages, client feedback, and win rates — so every iteration gets sharper and more profitable.`},{title:`Monitor & Alert`,description:`Computer can track competitor pricing changes and market shifts — and flag when it's time to update your packages.`}]});export{t as default};
